import{_ as a,o as n,c as i,ai as t}from"./chunks/framework.BI5prboT.js";const k=JSON.parse('{"title":"shuohao-skills","description":"","frontmatter":{},"headers":[],"relativePath":"AI/short-video/shuohao-skills.md","filePath":"AI/short-video/shuohao-skills.md"}'),l={name:"AI/short-video/shuohao-skills.md"};function e(p,s,o,h,r,d){return n(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="shuohao-skills" tabindex="-1">shuohao-skills <a class="header-anchor" href="#shuohao-skills" aria-label="Permalink to &quot;shuohao-skills&quot;">​</a></h1><p><a href="https://github.com/eternityspring/shuohao-skills" target="_blank" rel="noreferrer">shuohao-skills</a> 是一套 <strong>AI 短剧制作的 Agent Skill 集合</strong>，把一本小说从头跑到可直接喂生成管线的制作素材：拆角色、排大纲、出场景与道具设定、写剧本、切分镜。给 AI 编码 Agent 用，<strong>Claude Code 和 Codex 都能跑</strong>。</p><h2 id="整条管线" tabindex="-1">整条管线 <a class="header-anchor" href="#整条管线" aria-label="Permalink to &quot;整条管线&quot;">​</a></h2><p>五个 Skill 按流水线顺序协作，<strong>改编大纲收敛结构，剧本、场景、角色三者同步迭代，分镜只做输出不做新决定</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>小说原文</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>novel-outline      改编大纲（结构、爽点、分集梗概）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>novel-characters   角色设定集（画像、形象提示词、音色提示词）</span></span>
<span class="line"><span>novel-art          美术设定集（场景 + 叙事道具）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>novel-script       剧本（场次 + 节拍流、台词本）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>novel-storyboard   分镜（段 → 分镜 → 分镜图 → 投产包）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Skill</th><th>做什么</th></tr></thead><tbody><tr><td><strong>novel-outline</strong></td><td>把一本小说改编成短剧大纲五件套：改编说明、人物表、爽点表、分集梗概、资产清单。14 道质量门全部脚本检查，支持已有大纲的体检模式</td></tr><tr><td><strong>novel-characters</strong></td><td>把大纲定下的角色做成角色设定集：人物画像、形象提示词、音色提示词、角色设定图。吃 <code>outline.json</code> 预填角色表</td></tr><tr><td><strong>novel-art</strong></td><td>给 AI 短剧出美术设定集（场景 + 叙事道具）：一致性锚点、光照与状态变体、尺度参照、无人无手白底提示词。11 道质量门全部脚本检查</td></tr><tr><td><strong>novel-script</strong></td><td>写剧本：场次 + 节拍流（动作与台词交替），逐集时长按语速确定性折算，台词本按角色聚合带音色提示词直接对接 TTS。10 道质量门全部脚本检查</td></tr><tr><td><strong>novel-storyboard</strong></td><td>出分镜：段（一次生成 ≤15 秒）→ 分镜（2–5 秒硬门）→ 分镜图，MiniMax H3 提示词对齐，export 一键出投产包。17 道质量门全部脚本检查</td></tr></tbody></table><p>五个 Skill 的报告都支持中英双语界面：默认中文，<code>render --lang en</code> 出全英文报告。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/eternityspring/shuohao-skills.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shuohao-skills</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/install.sh</span></span></code></pre></div><p>脚本会自动检测本机装了 Claude Code 还是 Codex，把所有 Skill <strong>软链</strong>过去——<code>git pull</code> 之后立刻生效，不用重装。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/install.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> novel-characters</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 只装某一个</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --codex</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 只装到 codex</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --uninstall</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 取消软链</span></span></code></pre></div><p>手动软链也可以（路径换成当前 Agent 的 skills 目录）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/skills/novel-characters&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/skills/novel-characters</span></span></code></pre></div><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>必需？</th><th>说明</th></tr></thead><tbody><tr><td><strong>Node</strong></td><td>≥ 18。Skill 脚本只用标准库，<strong>没有 npm 依赖</strong></td></tr><tr><td><strong>模型额度</strong></td><td>用当前会话的额度，<strong>不需要任何 API key</strong></td></tr><tr><td><strong>codex CLI</strong></td><td>可选。出图才用得上（走内置 <code>$imagegen</code>），没有就跳过出图，其余产出照常</td></tr></tbody></table><h2 id="工作目录约定" tabindex="-1">工作目录约定 <a class="header-anchor" href="#工作目录约定" aria-label="Permalink to &quot;工作目录约定&quot;">​</a></h2><p>从头跑完五段，按 Skill 各建一个目录归档：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;demo&gt;/</span></span>
<span class="line"><span>├── outline/       ← novel-outline 产出</span></span>
<span class="line"><span>├── characters/    ← novel-characters 产出</span></span>
<span class="line"><span>├── art/           ← novel-art 产出</span></span>
<span class="line"><span>├── script/        ← novel-script 产出</span></span>
<span class="line"><span>├── storyboard/    ← novel-storyboard 产出 + export 投产包</span></span>
<span class="line"><span>│   ├── manifest.json</span></span>
<span class="line"><span>│   ├── E01-01/    ← 每段一个文件夹（prompt.md + f1..fN.png）</span></span>
<span class="line"><span>│   └── …</span></span>
<span class="line"><span>├── docs/</span></span>
<span class="line"><span>└── scripts/</span></span></code></pre></div><p>要点：</p><ul><li>每个 Skill 一个目录，装自己的 <code>json</code> / <code>md</code> / <code>html</code> 三件套</li><li>分镜的 <code>manifest.json</code> 与 <code>E01-0x/</code> 投产包一起归 <code>storyboard/</code></li><li><strong>段文件夹不要再往下收一层</strong>——报告 HTML 与段文件夹必须同级，多套一层目录，报告里的图会静默全变成「未生成」占位</li></ul><h2 id="合成单页报告" tabindex="-1">合成单页报告 <a class="header-anchor" href="#合成单页报告" aria-label="Permalink to &quot;合成单页报告&quot;">​</a></h2><p>五段的报告可以合成一张单页，左侧导航切换——有哪几段就出哪几个面板：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/report.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">demo目</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">录</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report.html</span></span></code></pre></div><p>它是<strong>组装器，不是独立 Skill</strong>：调各自的 <code>render --html</code> 拿产物再拼装，五个 Skill 各自仍然独立可跑。</p><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><p>安装后，在 Agent 对话里直接说意图即可触发对应 Skill，例如：</p><ul><li>「把这本小说改编成 60 集短剧大纲」→ <code>novel-outline</code></li><li>「根据 outline.json 出角色设定集」→ <code>novel-characters</code></li><li>「写第 3 集剧本」→ <code>novel-script</code></li><li>「给第 1 集出分镜并 export 投产包」→ <code>novel-storyboard</code></li></ul><p><strong>出图说明</strong>：大纲、剧本、分镜文案等全流程 Agent 都能跑；<code>novel-art</code> / <code>novel-storyboard</code> 的设定图、分镜图需要 <strong>Codex CLI</strong>（内置 <code>$imagegen</code>）或把提示词复制到 Midjourney / 即梦等外部平台。没有出图能力也不影响 json / md / html 报告产出。</p><p>每个 Skill 目录结构自包含，可以单独拷走：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>skills/&lt;skill-name&gt;/</span></span>
<span class="line"><span>├── SKILL.md          给 Agent 读的工作流（必需）</span></span>
<span class="line"><span>├── README.md         给人读的说明</span></span>
<span class="line"><span>├── scripts/</span></span>
<span class="line"><span>│   ├── &lt;name&gt;.mjs    确定性工具，零依赖</span></span>
<span class="line"><span>│   └── selftest.mjs  自测，不调模型（必需）</span></span>
<span class="line"><span>├── references/       按需加载的详细指令</span></span>
<span class="line"><span>├── examples/         自带样例</span></span>
<span class="line"><span>└── assets/           截图</span></span></code></pre></div><h2 id="质量门" tabindex="-1">质量门 <a class="header-anchor" href="#质量门" aria-label="Permalink to &quot;质量门&quot;">​</a></h2><p>每个 Skill 都有脚本化的质量门，<strong>不调用模型、不花额度</strong>，本地跑自测：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> f </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills/*/scripts/selftest.mjs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">done</span></span></code></pre></div><p>质量门覆盖角色分档上限、爽点间隔、分镜时长硬门、提示词对齐等对账等——不靠模型自觉。</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li>仓库：<a href="https://github.com/eternityspring/shuohao-skills" target="_blank" rel="noreferrer">github.com/eternityspring/shuohao-skills</a></li><li>本地 Skill 概念说明：<a href="./../skill.html">Skill 技能文件</a></li><li>怎么安装 Skill：<a href="./../skill-install.html">npx skills 怎么安装</a></li></ul>`,36)])])}const g=a(l,[["render",e]]);export{k as __pageData,g as default};
